"use client"

import * as React from "react"
import { Globe, Layers, Network, TriangleAlert } from "lucide-react"

import { cn } from "@/lib/utils"
import { analyzeCidr, formatAddress, formatSize, type ExistingRange } from "./cidr"

export { analyzeCidr, formatAddress, formatSize, type CidrAnalysis, type CidrOverlap, type ExistingRange } from "./cidr"

const fill = (template: string, values: Record<string, string | number>) =>
  template.replace(/\{(\w+)\}/g, (match, key: string) => String(values[key] ?? match))

const NONE: ExistingRange[] = []

const fieldClass =
  "h-9 w-full min-w-0 rounded-md border bg-transparent px-3 font-mono text-base shadow-xs transition-[color,box-shadow] outline-none placeholder:text-muted-foreground focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 disabled:cursor-not-allowed disabled:opacity-50 aria-invalid:border-destructive md:text-sm dark:bg-input/30 data-warning:border-amber-500 dark:data-warning:border-amber-400 data-danger:border-red-500 dark:data-danger:border-red-400"
const fixClass =
  "inline-flex h-6 items-center gap-1 rounded-md border border-amber-500/40 px-2 font-mono font-medium text-amber-900 transition-colors hover:bg-amber-500/10 dark:text-amber-200 outline-none focus-visible:ring-[3px] focus-visible:ring-ring/50"

export interface CidrInputProps extends Omit<React.ComponentProps<"input">, "value" | "defaultValue" | "onChange" | "type"> {
  /** Visible label. */
  label?: string
  /** Controlled value. */
  value?: string
  /** Initial value when uncontrolled. */
  defaultValue?: string
  /** Called with the text on every change. */
  onValueChange?: (value: string) => void
  /** Ranges already in use; an overlap with any of them is flagged by name. */
  existing?: ExistingRange[]
  /** Pause in ms before warnings appear while typing. Leaving the field shows them at once. */
  delay?: number
  /** Templates. `{first}`, `{last}`, `{count}`, `{network}`, `{host}`, `{prefix}`, `{label}`, `{cidr}`, `{all}` are filled in. */
  rangeText?: string
  hostBitsText?: string
  leadingZerosText?: string
  missingPrefixText?: string
  anywhereText?: string
  sameText?: string
  insideText?: string
  containsText?: string
}

/**
 * A CIDR field for firewall rules, VPCs and allowlists. It reads back the exact
 * range and address count, catches host bits set (10.0.0.1/8 silently means
 * all of 10.0.0.0/8, or was it just one host?) and offers both readings, warns
 * when a rule opens to the whole internet, and names any existing range it overlaps.
 */
export function CidrInput({
  label = "CIDR range",
  value,
  defaultValue = "",
  onValueChange,
  existing = NONE,
  delay = 500,
  rangeText = "{first} – {last} · {count} {addresses}",
  hostBitsText = "Host bits are set. Did you mean the network, or just this address?",
  leadingZerosText = "Leading zeros can be read as octal (010 = 8).",
  missingPrefixText = "No prefix, so this is a single address.",
  anywhereText = "This is open to the whole internet: every {all} address.",
  sameText = "Same range as {label} ({cidr}).",
  insideText = "Inside {label} ({cidr}).",
  containsText = "Contains {label} ({cidr}).",
  id,
  className,
  onBlur,
  ref,
  ...props
}: CidrInputProps) {
  const [inner, setInner] = React.useState(defaultValue)
  const [settled, setSettled] = React.useState(defaultValue)
  const inputRef = React.useRef<HTMLInputElement>(null)
  const autoId = React.useId()
  const inputId = id ?? autoId
  const text = value ?? inner

  React.useImperativeHandle(ref, () => inputRef.current as HTMLInputElement)

  React.useEffect(() => {
    const timer = setTimeout(() => setSettled(text), delay)
    return () => clearTimeout(timer)
  }, [text, delay])

  const update = (next: string) => {
    if (value === undefined) setInner(next)
    onValueChange?.(next)
  }
  const apply = (next: string) => {
    update(next)
    setSettled(next)
    inputRef.current?.focus()
  }

  const result = React.useMemo(() => (text.trim() ? analyzeCidr(text, existing) : null), [text, existing])
  const ready = settled === text
  const invalid = ready && result && !result.ok ? result : null
  const ok = result?.ok ? result : null
  const fullBits = ok ? (ok.family === 4 ? 32 : 128) : 32
  const host = ok ? `${formatAddress(ok.address, ok.family)}/${fullBits}` : ""
  const values: Record<string, string> = ok
    ? {
        first: formatAddress(ok.network, ok.family),
        last: formatAddress(ok.last, ok.family),
        count: formatSize(ok.size),
        addresses: ok.size === BigInt(1) ? "address" : "addresses",
        network: ok.canonical,
        host,
        prefix: `/${fullBits}`,
        all: `IPv${ok.family}`,
      }
    : {}
  const warnings: {
    key: string
    icon: typeof Globe
    text: string
    danger?: boolean
    fixes?: string[]
  }[] = []
  if (ok && ready) {
    if (ok.anywhere)
      warnings.push({
        key: "any",
        icon: Globe,
        text: fill(anywhereText, values),
        danger: true,
      })
    if (ok.hostBitsSet)
      warnings.push({
        key: "host",
        icon: TriangleAlert,
        text: fill(hostBitsText, values),
        fixes: [ok.canonical, host],
      })
    else if (ok.leadingZeros)
      warnings.push({
        key: "zeros",
        icon: TriangleAlert,
        text: leadingZerosText,
        fixes: [ok.canonical],
      })
    if (ok.missingPrefix)
      warnings.push({
        key: "prefix",
        icon: TriangleAlert,
        text: missingPrefixText,
        fixes: [host],
      })
    for (const overlap of ok.overlaps) {
      const template = {
        same: sameText,
        inside: insideText,
        contains: containsText,
      }[overlap.relation]
      const text = fill(template, {
        label: overlap.label ?? overlap.cidr,
        cidr: overlap.cidr,
      })
      warnings.push({ key: `overlap-${overlap.cidr}`, icon: Layers, text })
    }
  }
  const setHostBits = ok && ok.hostBitsSet ? ok.address & ~ok.network : BigInt(0)

  return (
    <div data-slot="cidr-input" className={cn("grid w-full max-w-sm gap-1.5", className)}>
      <label htmlFor={inputId} className="w-fit text-sm font-medium">
        {label}
      </label>
      <input
        ref={inputRef}
        id={inputId}
        type="text"
        inputMode="text"
        autoComplete="off"
        autoCapitalize="none"
        autoCorrect="off"
        spellCheck={false}
        value={text}
        onChange={(event) => update(event.target.value.replace(/\s+/g, ""))}
        onBlur={(event) => {
          setSettled(text)
          onBlur?.(event)
        }}
        aria-invalid={invalid ? true : undefined}
        aria-describedby={`${inputId}-hint`}
        data-warning={warnings.length && !invalid ? "" : undefined}
        data-danger={warnings.some((w) => w.danger) ? "" : undefined}
        className={fieldClass}
        {...props}
      />
      {/* One cell per bit: network bits solid, host bits faint, host bits that are set in amber. */}
      <div aria-hidden className={cn("flex h-1.5 overflow-hidden rounded-full", fullBits === 32 && "gap-px")}>
        {Array.from({ length: fullBits }, (_, bit) => {
          const set = (setHostBits >> BigInt(fullBits - 1 - bit)) & BigInt(1)
          return (
            <span
              key={bit}
              className={cn(
                "flex-1 transition-colors duration-200 ease-out motion-reduce:transition-none",
                !ok ? "bg-muted" : bit < ok.prefix ? "bg-foreground/70" : set ? "bg-amber-500 dark:bg-amber-400" : "bg-muted",
                fullBits === 128 && bit % 16 === 15 && bit < 127 && "mr-px",
              )}
            />
          )
        })}
      </div>
      <div id={`${inputId}-hint`} aria-live="polite" className="grid min-h-6 gap-1 text-xs">
        {ok && (
          <p className="flex items-center gap-1.5 py-1 text-muted-foreground">
            <Network aria-hidden className="size-3.5 shrink-0" />
            <span className="min-w-0 font-mono wrap-anywhere">{fill(rangeText, values)}</span>
          </p>
        )}
        {invalid && (
          <p role="alert" className="flex items-center gap-1.5 py-1 text-destructive">
            <TriangleAlert aria-hidden className="size-3.5 shrink-0" />
            {invalid.error}
          </p>
        )}
        {warnings.map(({ key, icon: Icon, text, danger, fixes }) => (
          <p
            key={key}
            className={cn("flex gap-1.5", danger ? "text-red-700 dark:text-red-400" : "text-amber-700 dark:text-amber-400")}
          >
            <span className="flex h-6 shrink-0 items-center">
              <Icon aria-hidden className="size-3.5" />
            </span>
            <span className="flex min-w-0 flex-wrap items-center gap-x-2 gap-y-1">
              <span className="py-1">{text}</span>
              {fixes?.map((fix) => (
                <button key={fix} type="button" onClick={() => apply(fix)} aria-label={`Use ${fix}`} className={fixClass}>
                  {fix}
                </button>
              ))}
            </span>
          </p>
        ))}
      </div>
    </div>
  )
}

/** Pure CIDR maths for IPv4 and IPv6, using BigInt so /0 and /128 are exact. */

export type IpFamily = 4 | 6

export interface ExistingRange {
  /** A CIDR such as "10.0.0.0/16". */
  cidr: string
  /** What it is, e.g. "prod-vpc". */
  label?: string
}

export interface CidrOverlap extends ExistingRange {
  /** How the typed range relates to the existing one. */
  relation: "same" | "inside" | "contains"
}

export type CidrAnalysis =
  | { ok: false; error: string; fix?: string; fixLabel?: string }
  | {
      ok: true
      family: IpFamily
      prefix: number
      /** Address bits as typed, before the mask is applied. */
      address: bigint
      network: bigint
      last: bigint
      /** Canonical form, e.g. "10.0.0.0/8". */
      canonical: string
      /** Number of addresses in the range. */
      size: bigint
      /** Typed address had bits set past the prefix: the canonical network and the single-host reading. */
      hostBitsSet: boolean
      /** 0.0.0.0/0 or ::/0. */
      anywhere: boolean
      /** Octets with leading zeros, which some parsers read as octal (010 = 8). */
      leadingZeros: boolean
      /** No "/prefix" was typed. */
      missingPrefix: boolean
      overlaps: CidrOverlap[]
    }

const bitsOf = (family: IpFamily) => (family === 4 ? 32 : 128)

function parseIPv4(text: string): { value: bigint; leadingZeros: boolean } | null {
  const parts = text.split(".")
  if (parts.length !== 4 || parts.some((part) => !/^\d{1,3}$/.test(part) || Number(part) > 255)) return null
  return {
    value: parts.reduce((acc, part) => (acc << BigInt(8)) | BigInt(Number(part)), BigInt(0)),
    leadingZeros: parts.some((part) => part.length > 1 && part.startsWith("0")),
  }
}

function parseIPv6(text: string): bigint | null {
  let groups: string[]
  // An embedded IPv4 tail (::ffff:10.0.0.1) counts as two groups.
  const tail = text.match(/:(\d+\.\d+\.\d+\.\d+)$/)
  if (tail) {
    const v4 = parseIPv4(tail[1])
    if (!v4) return null
    text = `${text.slice(0, -tail[1].length)}${(v4.value >> BigInt(16)).toString(16)}:${(v4.value & BigInt(0xffff)).toString(16)}`
  }
  const halves = text.split("::")
  if (halves.length > 2) return null
  const head = halves[0] ? halves[0].split(":") : []
  const rest = halves.length === 2 && halves[1] ? halves[1].split(":") : []
  if (halves.length === 2) {
    if (head.length + rest.length > 7) return null
    groups = [...head, ...Array<string>(8 - head.length - rest.length).fill("0"), ...rest]
  } else groups = head
  if (groups.length !== 8 || groups.some((group) => !/^[0-9a-f]{1,4}$/i.test(group))) return null
  return groups.reduce((acc, group) => (acc << BigInt(16)) | BigInt(parseInt(group, 16)), BigInt(0))
}

/** Formats an address: dotted IPv4, or RFC 5952 IPv6 (lowercase, longest zero run as ::). */
export function formatAddress(value: bigint, family: IpFamily): string {
  if (family === 4) return [24, 16, 8, 0].map((shift) => Number((value >> BigInt(shift)) & BigInt(255))).join(".")
  const groups = Array.from({ length: 8 }, (_, i) => Number((value >> BigInt(112 - i * 16)) & BigInt(0xffff)))
  let best = { start: -1, length: 1 }
  for (let i = 0; i < 8; i++) {
    let j = i
    while (j < 8 && groups[j] === 0) j++
    if (j - i > best.length) best = { start: i, length: j - i }
    i = j
  }
  const hex = groups.map((group) => group.toString(16))
  if (best.start < 0) return hex.join(":")
  return `${hex.slice(0, best.start).join(":")}::${hex.slice(best.start + best.length).join(":")}`
}

function parseCidr(input: string) {
  const [addressText, prefixText, ...extra] = input.trim().split("/")
  if (extra.length) return null
  const family: IpFamily = addressText.includes(":") ? 6 : 4
  const v4 = family === 4 ? parseIPv4(addressText) : null
  const address = family === 4 ? v4?.value : parseIPv6(addressText)
  if (address === undefined || address === null) return null
  const bits = bitsOf(family)
  const prefix = prefixText === undefined ? bits : /^\d{1,3}$/.test(prefixText) ? Number(prefixText) : NaN
  return {
    family,
    address,
    prefix,
    bits,
    leadingZeros: !!v4?.leadingZeros,
    missingPrefix: prefixText === undefined,
  }
}

const maskOf = (prefix: number, bits: number) =>
  ((BigInt(1) << BigInt(bits)) - BigInt(1)) ^ ((BigInt(1) << BigInt(bits - prefix)) - BigInt(1))

/** Validates a CIDR and describes its range, host-bit slips, open-to-everyone blocks and overlaps. */
export function analyzeCidr(input: string, existing: ExistingRange[] = []): CidrAnalysis {
  const text = input.trim()
  const parsed = parseCidr(text)
  if (!parsed) {
    if (/^[\d.]+\s*-\s*[\d.]+$/.test(text))
      return {
        ok: false,
        error: "Use CIDR notation (10.0.0.0/24), not a dash range.",
      }
    return {
      ok: false,
      error: text.includes(":") ? "That isn't a valid IPv6 address." : "That isn't a valid IP address.",
    }
  }
  const { family, address, prefix, bits } = parsed
  if (!Number.isInteger(prefix) || prefix > bits) {
    return {
      ok: false,
      error: `The prefix after / must be 0–${bits} for IPv${family}.`,
    }
  }
  const mask = maskOf(prefix, bits)
  const network = address & mask
  const last = network | (((BigInt(1) << BigInt(bits)) - BigInt(1)) ^ mask)
  const overlaps: CidrOverlap[] = []
  for (const range of existing) {
    const other = parseCidr(range.cidr)
    if (!other || other.family !== family || !Number.isInteger(other.prefix)) continue
    const otherNetwork = other.address & maskOf(other.prefix, bits)
    const otherLast = otherNetwork | (((BigInt(1) << BigInt(bits)) - BigInt(1)) ^ maskOf(other.prefix, bits))
    // Two CIDR blocks are either disjoint or one sits inside the other.
    if (otherLast < network || otherNetwork > last) continue
    const relation = other.prefix === prefix ? "same" : other.prefix < prefix ? "inside" : "contains"
    overlaps.push({ ...range, relation })
  }
  return {
    ok: true,
    family,
    prefix,
    address,
    network,
    last,
    canonical: `${formatAddress(network, family)}/${prefix}`,
    size: BigInt(1) << BigInt(bits - prefix),
    hostBitsSet: network !== address,
    anywhere: prefix === 0,
    leadingZeros: parsed.leadingZeros,
    missingPrefix: parsed.missingPrefix,
    overlaps,
  }
}

const superscript = (n: number) => String(n).replace(/\d/g, (d) => "⁰¹²³⁴⁵⁶⁷⁸⁹"[Number(d)])

/** "65,536", or "2⁶⁴" once the exact number stops being readable. */
export function formatSize(size: bigint): string {
  const exponent = size.toString(2).length - 1
  return exponent > 32 ? `2${superscript(exponent)}` : size.toLocaleString("en-US")
}
